import { api, PAGE_SIZE, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/estimation/work/instance/';
export const workInstanceApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listWorkInstance: build.query({
            query: ({ page, size, projectId, blockId, category, schId }) => {
                let url = urlUtils(API_PATH, `?page=${page || 1}&page_size=${size || PAGE_SIZE}`);
                if (projectId)
                    url += `&proj_key=${projectId}`;
                if (blockId)
                    url += `&projblk_key=${blockId}`;
                if (category)
                    url += `&category=${category}`;
                if (schId)
                    url += `&sch_id=${schId}`;
                return { url };
            },
            providesTags: (result) => result
                ? [
                    ...result.results.map(({ key }) => ({ type: tags.WHOLE_ROD_PACK, key })),
                    { type: tags.WHOLE_ROD_PACK, id: 'LIST' },
                ]
                : [{ type: tags.WHOLE_ROD_PACK, id: 'LIST' }],
        }),
        getWorkInstance: build.query({
            query: (id) => `${API_PATH}${id}/`,
            providesTags: (_result, _err, id) => [{ type: tags.WHOLE_ROD_PACK, id }],
        }),
        addWorkInstance: build.mutation({
            query: (body) => ({ url: API_PATH, method: 'POST', body }),
            invalidatesTags: [{ type: tags.WHOLE_ROD_PACK, id: 'LIST' }],
        }),
        addBulkWorkInstances: build.mutation({
            query: (body) => ({ url: API_PATH, method: 'POST', body }),
            invalidatesTags: [{ type: tags.WHOLE_ROD_PACK, id: 'LIST' }],
        }),
        updateWorkInstance: build.mutation({
            query: (body) => ({ url: `${API_PATH}${body.key}/`, method: 'PUT', body }),
            invalidatesTags: (wi) => [{ type: tags.WHOLE_ROD_PACK, id: wi === null || wi === void 0 ? void 0 : wi.key }],
        }),
        deleteWorkInstance: build.mutation({
            query: (id) => ({ url: `${API_PATH}${id}/`, method: 'DELETE' }),
            invalidatesTags: (wi) => [{ type: tags.WHOLE_ROD_PACK, id: wi === null || wi === void 0 ? void 0 : wi.id }],
        }),
    }),
});
export const { useListWorkInstanceQuery, useGetWorkInstanceQuery, useAddWorkInstanceMutation, useAddBulkWorkInstancesMutation, useUpdateWorkInstanceMutation, useDeleteWorkInstanceMutation, } = workInstanceApi;
